import math
import sys

def main():
    input = sys.stdin.read().strip().split()
    n = int(input[0])
    if n > 11:
        print(0)
        return
    points = []
    index = 1
    for _ in range(n):
        point = list(map(int, input[index:index+5]))
        index += 5
        points.append(point)
    indices = []
    for i in range(n):
        valid_point = True
        for j in range(n):
            if j == i:
                continue
            for k in range(j + 1, n):
                if k == i:
                    continue
                vA = Vector(points[i], points[j])
                vB = Vector(points[i], points[k])
                angle = math.acos(vA.prod(vB) / (vA.mag() * vB.mag()))
                if angle < math.pi/2 - 1e-9:
                    valid_point = False
                    break
            if not valid_point:
                break
        if valid_point:
            indices.append(i + 1)
    print(len(indices))
    for idx in indices:
        print(idx)

class Vector:
    def __init__(self, a, b):
        self.vec = [b[i] - a[i] for i in range(5)]
    def mag(self):
        return math.sqrt(sum(c * c for c in self.vec))
    def prod(self, v):
        return sum(self.vec[i] * v.vec[i] for i in range(5))

if __name__ == "__main__":
    main()

